#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod mop_units;

use std::path::PathBuf;

use faer::Col;
use mopt_rs::core_infra::json::JsonValue;
use mopt_rs::domain::{positions, Bohr, Element, MolecularSystem, SpinCharge};
use mopt_rs::opt::state_machine::{Action, GeometryOptimizer, OptimizerSettings};

fn golden(name: &str) -> JsonValue {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/golden")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    JsonValue::parse(&text).unwrap()
}

fn floats(v: &JsonValue) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

/// Run the case of a golden file and return the index of the first frame whose coordinates
/// differ from the reference by more than `tol` (`None`: all frames agree), with the number of
/// reference frames.
fn first_divergence(file: &str, tol: f64) -> (Option<usize>, usize) {
    let g = golden(file);
    let args: Vec<String> = g.get("arguments").unwrap().as_string_vec().unwrap();
    let mut settings = OptimizerSettings::default();
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.as_str() {
            "-opt" => settings.methods = vec![it.next().unwrap().clone()],
            "-ns" => settings.max_iterations = it.next().unwrap().parse().unwrap(),
            _ => {}
        }
    }
    let el: Vec<Element> = g
        .get("symbols")
        .unwrap()
        .as_string_vec()
        .unwrap()
        .iter()
        .map(|s| Element::parse_token(s).unwrap())
        .collect();
    let x0 = floats(g.get("initial_coords_bohr").unwrap());
    let pos: Vec<[f64; 3]> = x0.chunks(3).map(|c| [c[0], c[1], c[2]]).collect();
    let start =
        MolecularSystem::new(el, &positions::<Bohr>(&pos), SpinCharge::default(), None).unwrap();
    let mut opt = GeometryOptimizer::new(settings, start).unwrap();
    let mut coords: Vec<Col<f64>> = Vec::new();
    while let Action::Evaluate(tasks) = opt.ask() {
        // MultiOptPy's numbers are in its own Bohr and Hartree (see `mop_units`).
        let out = mop_units::lennard_jones(&tasks[0].system, &tasks[0].request).unwrap();
        coords.push(tasks[0].system.coords_flat_bohr());
        opt.tell_one(out).unwrap();
    }
    let frames = g.get("frames").unwrap().as_array().unwrap();
    for (k, f) in frames.iter().enumerate() {
        let Some(x) = coords.get(k) else {
            return (Some(k), frames.len());
        };
        let x_ref = floats(f.get("coords_bohr").unwrap());
        if x.iter().zip(&x_ref).any(|(a, b)| (a - b).abs() > tol) {
            return (Some(k), frames.len());
        }
    }
    (None, frames.len())
}

#[test]
fn first_order_methods_follow_multioptpy() {
    for file in [
        "opt_lj_ar7_gradientdescent.json",
        "opt_lj_ar7_mwgradientdescent.json",
        "opt_lj_ar7_adamlars.json",
        "opt_lj_ar7_radam.json",
        "opt_lj_ar7_adabelief.json",
        "opt_lj_ar7_eve.json",
        "opt_lj_ar7_fire2.json",
    ] {
        let (div, n) = first_divergence(file, 1e-9);
        eprintln!("{file}: {n} reference frames, first divergence {div:?}");
        assert_eq!(div, None, "{file}");
        assert_eq!(n, 30, "{file}");
    }
}

#[test]
fn coordinate_locking_and_component_wise_scaling_follow_multioptpy() {
    for file in [
        "opt_lj_ar7_fire_locking.json",
        "opt_lj_ar7_fire_scaling.json",
    ] {
        let (div, n) = first_divergence(file, 1e-9);
        eprintln!("{file}: {n} reference frames, first divergence {div:?}");
        assert_eq!(div, None, "{file}");
        assert_eq!(n, 30, "{file}");
    }
}
